function check4($v,$m){global$checks;network_check($v,'FAIL '.$m);$checks++;echo 'PASS '.$m,PHP_EOL;}
function req4($path,$data=null,$who='public'){global$dir;$c=curl_init('http://127.0.0.1:8798'.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$dir.'/task4-cookie-'.$who,CURLOPT_COOKIEFILE=>$dir.'/task4-cookie-'.$who,CURLOPT_TIMEOUT=>30]);if($data!==null)curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($data)]);$raw=curl_exec($c);network_check($raw!==false,'Request failed');$n=curl_getinfo($c,CURLINFO_HEADER_SIZE);$r=['status'=>in_array(curl_getinfo($c,CURLINFO_RESPONSE_CODE),[302,303,307],true)?302:curl_getinfo($c,CURLINFO_RESPONSE_CODE),'headers'=>substr($raw,0,$n),'body'=>substr($raw,$n)];curl_close($c);return$r;}
function tok4($path,$name,$who='public'){$r=req4($path,null,$who);network_check(preg_match('/name="'.$name.'" value="([a-f0-9]+)"/',$r['body'],$m),'Missing CSRF '.$path);return$m[1];}
