check4(req4('/library-workspace/records/books')['status']===302,'Activation session cannot skip password setup');check4(req4('/library-workspace/loans',[])['status']===403,'Activation session cannot mutate operations');$r=req4('/library-workspace/account');check4($r['status']===200&&!str_contains($r['body'],'name="current_password"'),'Verified activation does not need old password');
$t=tok4('/library-workspace/account','network_csrf');$password='SchoolPersonal!Task4';$r=req4('/library-workspace/account',['network_csrf'=>$t,'password'=>$password,'confirmation'=>$password]);check4($r['status']===302,'New password saved');$user=$db->where('username',$meta['http']['username'])->get('auth_user')->row_array();check4(password_verify($password,$user['password_hash'])&&(int)$user['force_password_change']===0,'Password is personal and activation completed');check4(req4('/library-workspace')['status']===200,'Operational dashboard available after setup');check4(req4('/library-activation')['status']===403,'Activated local account cannot issue codes');check4(str_contains(req4('/library-workspace/account')['body'],'name="current_password"'),'Activation bypass consumed; next password change requires current password');
req4('/logout');$t=tok4('/aktivasi-perpustakaan','activation_csrf');$r=req4('/aktivasi-perpustakaan/klaim',array_replace($base,['activation_csrf'=>$t]));check4($r['status']===302&&str_contains(req4('/aktivasi-perpustakaan')['body'],'sudah pernah digunakan'),'Reclaim rejected after logout');$r=req4('/auth/do_login',['identifier'=>$meta['http']['username'],'password'=>$password]);check4($r['status']===302&&str_contains($r['headers'],'library-workspace'),'Personal password login works');
req4('/logout');$t=tok4('/aktivasi-perpustakaan','activation_csrf');$r=req4('/aktivasi-perpustakaan/klaim',['library_id'=>2,'activation_code'=>$once,'ownership'=>1,'activation_csrf'=>$t]);check4(str_contains(req4('/aktivasi-perpustakaan')['body'],'tidak dapat diaktivasi'),'Central library blocked on public endpoint');
